use std::fs;
use std::path::Path;

const SEED: u64 = 0x5EED_CAFE_2025_0001;
const N_ROWS: usize = 1000;
const REGIONS: [&str; 4] = ["North", "South", "East", "West"];
const QUARTERS: [&str; 4] = ["Q1", "Q2", "Q3", "Q4"];
const MIN_CENTS: u64 = 10_000; // $100.00
const MAX_CENTS: u64 = 1_000_000; // $10000.00

// ---------- PRNG: SplitMix64 (deterministic, fixed seed) ----------
struct SplitMix64 { state: u64 }

impl SplitMix64 {
    fn new(seed: u64) -> Self { Self { state: seed } }
    fn next_u64(&mut self) -> u64 {
        self.state = self.state.wrapping_add(0x9E37_79B9_7F4A_7C15);
        let mut z = self.state;
        z = (z ^ (z >> 30)).wrapping_mul(0xBF58_476D_1CE4_E5B9);
        z = (z ^ (z >> 27)).wrapping_mul(0x94D0_49BB_1331_11EB);
        z ^ (z >> 31)
    }
    // uniform in [lo, hi] inclusive
    fn next_inclusive(&mut self, lo: u64, hi: u64) -> u64 {
        debug_assert!(hi >= lo);
        lo + self.next_u64() % (hi - lo + 1)
    }
}

fn is_leap(y: i32) -> bool { (y % 4 == 0 && y % 100 != 0) || y % 400 == 0 }

fn days_in_month(y: i32, m: u32) -> u32 {
    match m {
        1 | 3 | 5 | 7 | 8 | 10 | 12 => 31,
        4 | 6 | 9 | 11 => 30,
        2 => if is_leap(y) { 29 } else { 28 },
        _ => 0,
    }
}

struct Row { id: u64, region: usize, year: i32, month: u32, day: u32, cents: u64 }

fn quarter_of(m: u32) -> usize { ((m - 1) / 3) as usize }

// money from integer cents, exactly two decimals, no float drift
fn money(cents: u64) -> String { format!("{}.{:02}", cents / 100, cents % 100) }

fn json_escape(s: &str) -> String {
    let mut out = String::with_capacity(s.len());
    for c in s.chars() {
        match c {
            '"' => out.push_str("\\\""),
            '\\' => out.push_str("\\\\"),
            '\n' => out.push_str("\\n"),
            '\r' => out.push_str("\\r"),
            '\t' => out.push_str("\\t"),
            c if (c as u32) < 0x20 => out.push_str(&format!("\\u{:04x}", c as u32)),
            c => out.push(c),
        }
    }
    out
}

fn generate_rows(n: usize, rng: &mut SplitMix64) -> Vec<Row> {
    let mut rows = Vec::with_capacity(n);
    for id in 1..=n as u64 {
        let region = rng.next_inclusive(0, 3) as usize;
        let month = rng.next_inclusive(1, 12) as u32;
        let dim = days_in_month(2025, month);
        let day = rng.next_inclusive(1, dim as u64) as u32;
        let cents = rng.next_inclusive(MIN_CENTS, MAX_CENTS);
        rows.push(Row { id, region, year: 2025, month, day, cents });
    }
    rows
}

fn build_json(rows: &[Row], qt: &[u64; 4], rt: &[u64; 4], grand: u64) -> String {
    let mut s = String::with_capacity(rows.len() * 96 + 512);
    s.push_str("{\n  \"rows\": [\n");
    for (i, r) in rows.iter().enumerate() {
        s.push_str(&format!(
            "    {{\"id\": {}, \"region\": \"{}\", \"date\": \"{}-{:02}-{:02}\", \"amount\": {}}}",
            r.id, json_escape(REGIONS[r.region]), r.year, r.month, r.day, money(r.cents)
        ));
        if i + 1 < rows.len() { s.push(','); }
        s.push('\n');
    }
    s.push_str("  ],\n  \"quarter_totals\": {\n");
    for (i, (name, v)) in QUARTERS.iter().zip(qt.iter()).enumerate() {
        s.push_str(&format!("    \"{}\": {}", name, money(*v)));
        if i + 1 < 4 { s.push(','); }
        s.push('\n');
    }
    s.push_str("  },\n  \"region_totals\": {\n");
    for (i, (name, v)) in REGIONS.iter().zip(rt.iter()).enumerate() {
        s.push_str(&format!("    \"{}\": {}", json_escape(name), money(*v)));
        if i + 1 < 4 { s.push(','); }
        s.push('\n');
    }
    s.push_str("  },\n");
    s.push_str(&format!("  \"grand_total\": {}\n}}\n", money(grand)));
    s
}

// ---------- minimal strict JSON syntax validator (RFC 8259 subset) ----------
struct Json { b: Vec<u8>, i: usize }

impl Json {
    fn new(s: &str) -> Self { Json { b: s.as_bytes().to_vec(), i: 0 } }
    fn ws(&mut self) {
        while let Some(&c) = self.b.get(self.i) {
            if c == b' ' || c == b'\t' || c == b'\n' || c == b'\r' { self.i += 1; } else { break; }
        }
    }
    fn peek(&self) -> Option<u8> { self.b.get(self.i).copied() }
    fn eat(&mut self, c: u8) -> Result<(), String> {
        if self.peek() == Some(c) { self.i += 1; Ok(()) } else { Err(format!("expected '{}' at byte {}", c as char, self.i)) }
    }
    fn lit(&mut self, l: &str) -> Result<(), String> {
        if self.b[self.i..].starts_with(l.as_bytes()) { self.i += l.len(); Ok(()) } else { Err(format!("bad literal at byte {}", self.i)) }
    }
    fn string(&mut self) -> Result<(), String> {
        self.eat(b'"')?;
        loop {
            match self.peek() {
                None => return Err("unterminated string".into()),
                Some(b'"') => { self.i += 1; return Ok(()); }
                Some(b'\\') => {
                    self.i += 1;
                    match self.peek() {
                        Some(b'"') | Some(b'\\') | Some(b'/') | Some(b'b') | Some(b'f') | Some(b'n') | Some(b'r') | Some(b't') => { self.i += 1; }
                        Some(b'u') => {
                            self.i += 1;
                            for _ in 0..4 {
                                let c = self.peek().ok_or_else(|| "bad \\u escape".to_string())?;
                                if !c.is_ascii_hexdigit() { return Err(format!("bad \\u escape at byte {}", self.i)); }
                                self.i += 1;
                            }
                        }
                        _ => return Err(format!("bad escape at byte {}", self.i)),
                    }
                }
                Some(c) if c < 0x20 => return Err(format!("raw control char in string at byte {}", self.i)),
                Some(_) => { self.i += 1; }
            }
        }
    }
    fn number(&mut self) -> Result<(), String> {
        if self.peek() == Some(b'-') { self.i += 1; }
        match self.peek() {
            Some(b'0') => { self.i += 1; }
            Some(c) if c.is_ascii_digit() => { while matches!(self.peek(), Some(c) if c.is_ascii_digit()) { self.i += 1; } }
            _ => return Err(format!("bad number at byte {}", self.i)),
        }
        if self.peek() == Some(b'.') {
            self.i += 1;
            if !matches!(self.peek(), Some(c) if c.is_ascii_digit()) { return Err("bad fraction".into()); }
            while matches!(self.peek(), Some(c) if c.is_ascii_digit()) { self.i += 1; }
        }
        if matches!(self.peek(), Some(b'e') | Some(b'E')) {
            self.i += 1;
            if matches!(self.peek(), Some(b'+') | Some(b'-')) { self.i += 1; }
            if !matches!(self.peek(), Some(c) if c.is_ascii_digit()) { return Err("bad exponent".into()); }
            while matches!(self.peek(), Some(c) if c.is_ascii_digit()) { self.i += 1; }
        }
        Ok(())
    }
    fn value(&mut self) -> Result<(), String> {
        self.ws();
        match self.peek() {
            Some(b'{') => {
                self.i += 1;
                self.ws();
                if self.peek() == Some(b'}') { self.i += 1; return Ok(()); }
                loop {
                    self.ws(); self.string()?; self.ws(); self.eat(b':')?; self.value()?; self.ws();
                    match self.peek() {
                        Some(b',') => { self.i += 1; }
                        Some(b'}') => { self.i += 1; return Ok(()); }
                        _ => return Err(format!("expected ',' or '}}' at byte {}", self.i)),
                    }
                }
            }
            Some(b'[') => {
                self.i += 1;
                self.ws();
                if self.peek() == Some(b']') { self.i += 1; return Ok(()); }
                loop {
                    self.value()?; self.ws();
                    match self.peek() {
                        Some(b',') => { self.i += 1; }
                        Some(b']') => { self.i += 1; return Ok(()); }
                        _ => return Err(format!("expected ',' or ']' at byte {}", self.i)),
                    }
                }
            }
            Some(b'"') => self.string(),
            Some(b't') => self.lit("true"),
            Some(b'f') => self.lit("false"),
            Some(b'n') => self.lit("null"),
            Some(c) if c == b'-' || c.is_ascii_digit() => self.number(),
            _ => Err(format!("unexpected byte at {}", self.i)),
        }
    }
    fn validate_top(&mut self) -> Result<(), String> {
        self.value()?;
        self.ws();
        if self.i != self.b.len() { return Err(format!("trailing bytes at {}", self.i)); }
        Ok(())
    }
}

fn main() {
    let dir = Path::new("/work/artifacts");
    fs::create_dir_all(dir).expect("create /work/artifacts");

    // 1) deterministic PRNG, 2) generate exactly 1000 rows
    let mut rng = SplitMix64::new(SEED);
    let rows = generate_rows(N_ROWS, &mut rng);

    // 3) totals per quarter and per region, in integer cents
    let mut quarter_totals = [0u64; 4];
    let mut region_totals = [0u64; 4];
    let mut grand: u64 = 0;
    for r in &rows {
        quarter_totals[quarter_of(r.month)] += r.cents;
        region_totals[r.region] += r.cents;
        grand += r.cents;
    }

    // 6) assertions before writing (panic on failure)
    assert_eq!(rows.len(), N_ROWS, "row count must be exactly 1000");
    for (i, r) in rows.iter().enumerate() {
        assert_eq!(r.id, (i + 1) as u64, "ids must be 1..=1000 in order (row {})", i);
        assert_eq!(r.year, 2025, "id {}: year must be 2025", r.id);
        assert!((1..=12).contains(&r.month), "id {}: month {} out of range", r.id, r.month);
        let dim = days_in_month(r.year, r.month);
        assert!(r.day >= 1 && r.day <= dim, "id {}: day {} invalid for {}-{:02}", r.id, r.day, r.year, r.month);
        assert!(r.region < REGIONS.len(), "id {}: region index out of range", r.id);
        assert!((MIN_CENTS..=MAX_CENTS).contains(&r.cents), "id {}: amount out of range", r.id);
    }
    let qsum: u64 = quarter_totals.iter().sum();
    assert_eq!(qsum, grand, "quarter totals must sum to grand total");
    let rsum: u64 = region_totals.iter().sum();
    assert_eq!(rsum, grand, "region totals must sum to grand total");
    assert!(grand > 0, "grand total must be positive");

    // 4) build and write JSON
    let json = build_json(&rows, &quarter_totals, &region_totals, grand);
    let out_path = dir.join("result.json");
    fs::write(&out_path, &json).expect("write result.json");

    // post-write verification: exists, right size, valid JSON, 1000 rows, grand total matches
    assert!(out_path.exists(), "result.json must exist after write");
    let written = fs::read_to_string(&out_path).expect("read back result.json");
    assert_eq!(written.len(), json.len(), "file size must match written JSON");
    let mut v = Json::new(&written);
    if let Err(e) = v.validate_top() {
        panic!("result.json is not valid JSON: {}", e);
    }
    let id_count = written.matches("\"id\":").count();
    assert_eq!(id_count, N_ROWS, "result.json must contain 1000 row objects, found {}", id_count);
    for key in ["\"quarter_totals\"", "\"region_totals\"", "\"grand_total\""] {
        assert!(written.contains(key), "result.json missing key {}", key);
    }
    let gt_line = format!("\"grand_total\": {}", money(grand));
    assert!(written.contains(&gt_line), "grand_total in file must match computed value"

